// Import group types
const (
	GroupStd     = "std"
	GroupGeneral = "general"
	GroupCompany = "company"
	GroupProject = "project"
	GroupBlanked = "blanked"
	GroupDotted  = "dotted"
)

// ParseImportsOrder parses a comma-separated imports-order string.
// It must contain at least the 4 required types: std, general, company, project.
// Additionally it may contain: blanked, dotted.
func ParseImportsOrder(s string) ([]string, error) {
	parts := strings.Split(s, ",")
	for i := range parts {
		parts[i] = strings.TrimSpace(parts[i])
	}

	valid := map[string]struct{}{
		GroupStd: {}, GroupGeneral: {}, GroupCompany: {}, GroupProject: {},
		GroupBlanked: {}, GroupDotted: {},
	}

	for _, p := range parts {
		if _, ok := valid[p]; !ok {
			return nil, fmt.Errorf("unknown order group type: %q", p)
		}
	}

	// Must contain at least 4 required types
	required := []string{GroupStd, GroupGeneral, GroupCompany, GroupProject}
	for _, r := range required {
		found := false
		for _, p := range parts {
			if p == r {
				found = true
				break
			}
		}
		if !found {
			return nil, fmt.Errorf(`use default at least 4 parameters to sort groups of your imports: "std,general,company,project"`)
		}
	}

	return parts, nil
}

// HasGroup returns true if group is in the order list.
func HasGroup(order []string, group string) bool {
	for _, o := range order {
		if o == group {
			return true
		}
	}
	return false
}
