package reviser

import (
	"crypto/md5"
	"encoding/hex"
	"fmt"
	"io/ioutil"
	"os"
	"path/filepath"
	"strings"
)

// Process processes a single path (file, directory, or ./... pattern).
// Returns whether any file was changed, and an error if any.
func Process(path string, cfg *Config) (bool, error) {
	// Handle "./..." style patterns
	if strings.HasSuffix(path, "/...") || path == "..." {
		root := strings.TrimSuffix(path, "...")
		if root == "" || root == "./" {
			root = "."
		} else {
			root = strings.TrimSuffix(root, "/")
		}
		return processDir(root, true, cfg)
	}

	info, err := os.Stat(path)
	if err != nil {
		return false, err
	}

	if info.IsDir() {
		return processDir(path, cfg.Recursive, cfg)
	}

	// Single file
	return processFile(path, cfg)
}

func processDir(dir string, recursive bool, cfg *Config) (bool, error) {
	changed := false

	// Auto-detect project name from go.mod if not set
	if cfg.ProjectName == "" {
		pn, err := findProjectName(dir)
		if err != nil {
			return false, err
		}
		cfg.ProjectName = pn
	}

	var files []string
	if recursive {
		err := filepath.Walk(dir, func(p string, info os.FileInfo, err error) error {
			if err != nil {
				return err
			}
			if info.IsDir() {
				if isExcluded(p, cfg.Excludes) {
					return filepath.SkipDir
				}
				// Skip common hidden dirs
				base := filepath.Base(p)
				if base != "." && strings.HasPrefix(base, ".") && p != dir {
					return filepath.SkipDir
				}
				return nil
			}
			if !strings.HasSuffix(p, ".go") {
				return nil
			}
			if isExcluded(p, cfg.Excludes) {
				return nil
			}
			files = append(files, p)
			return nil
		})
		if err != nil {
			return false, err
		}
	} else {
		entries, err := ioutil.ReadDir(dir)
		if err != nil {
			return false, err
		}
		for _, e := range entries {
			if e.IsDir() {
				continue
			}
			if !strings.HasSuffix(e.Name(), ".go") {
				continue
			}
			p := filepath.Join(dir, e.Name())
			if isExcluded(p, cfg.Excludes) {
				continue
			}
			files = append(files, p)
		}
	}

	for _, f := range files {
		c, err := processFile(f, cfg)
		if err != nil {
			return changed, err
		}
		if c {
			changed = true
		}
	}

	return changed, nil
}

func isExcluded(path string, excludes []string) bool {
	for _, ex := range excludes {
		// Match if path contains exclude pattern as suffix or substring
		if strings.HasSuffix(ex, "/") {
			// directory exclusion
			prefix := strings.TrimSuffix(ex, "/")
			// Check if any component of the path matches
			parts := strings.Split(path, string(filepath.Separator))
			for _, part := range parts {
				if part == prefix {
					return true
				}
			}
			// Also match if path starts with this
			if strings.HasPrefix(path, prefix+"/") || path == prefix {
				return true
			}
			continue
		}
		// Glob-like matching: try matching the base name
		base := filepath.Base(path)
		matched, _ := filepath.Match(ex, base)
		if matched {
			return true
		}
