func isExcluded(path string, excludes []string) bool {
	for _, ex := range excludes {
		// Match if path contains exclude pattern as suffix or substring
		if strings.HasSuffix(ex, "/") {
			// directory exclusion
			prefix := strings.TrimSuffix(ex, "/")
			// Check if any component of the path matches
			parts := strings.Split(path, string(filepath.Separator))
			for _, part := range parts {
				if part == prefix {
					return true
				}
			}
			// Also match if path starts with this
			if strings.HasPrefix(path, prefix+"/") || path == prefix {
				return true
			}
			continue
		}
		// Glob-like matching: try matching the base name
		base := filepath.Base(path)
		matched, _ := filepath.Match(ex, base)
		if matched {
			return true
		}
		// Try matching the full pattern against path with filepath.Match
		matched, _ = filepath.Match(ex, path)
		if matched {
			return true
		}
		// Also allow substring matching for patterns with '/'
		if strings.Contains(ex, "/") {
			// Try matching against relative path components
			matched, _ = filepath.Match(ex, path)
			if matched {
				return true
			}
			// Check if any path segment-to-end matches
			pathParts := strings.Split(path, string(filepath.Separator))
			for i := 0; i < len(pathParts); i++ {
				sub := strings.Join(pathParts[i:], "/")
				matched, _ = filepath.Match(ex, sub)
				if matched {
					return true
				}
			}
		}
	}
	return false
}

func processFile(path string, cfg *Config) (bool, error) {
	// Detect or use provided project name
	projectName := cfg.ProjectName
	if projectName == "" {
		pn, err := findProjectName(path)
		if err != nil {
			return false, fmt.Errorf("Could not determine project name for path %s: %w", path, err)
		}
		projectName = pn
	}

	absPath, _ := filepath.Abs(path)

	origContent, err := ioutil.ReadFile(path)
	if err != nil {
		return false, err
	}

	// Check cache
	if cfg.UseCache {
		cacheFile := cacheFilePath(absPath)
		hash := md5Hex(origContent)
		if existing, err := ioutil.ReadFile(cacheFile); err == nil {
			if string(existing) == hash {
				return false, nil
			}
		}
	}

	// Process the file
	newContent, changed, err := reviseFile(path, origContent, projectName, cfg)
	if err != nil {
		return false, err
	}

	// Output handling
	switch cfg.Output {
	case "stdout":
		os.Stdout.Write(newContent)
	case "write":
		if cfg.ListDiff {
			// Write back AND list the filename
			if changed {
				if err := ioutil.WriteFile(path, newContent, 0644); err != nil {
					return changed, err
				}
			}
			fmt.Println(absPath)
		} else {
			if changed {
				if err := ioutil.WriteFile(path, newContent, 0644); err != nil {
					return changed, err
				}
			}
		}
	case "file":
		if cfg.ListDiff {
			// Don't write, just list
			fmt.Println(absPath)
		} else {
			if changed {
				if err := ioutil.WriteFile(path, newContent, 0644); err != nil {
					return changed, err
				}
			}
		}
	}

	// Update cache
	if cfg.UseCache {
		cacheFile := cacheFilePath(absPath)
		os.MkdirAll(filepath.Dir(cacheFile), 0755)
		// Use newContent hash (since that's what's on disk now, after write)
		hash := md5Hex(newContent)
		ioutil.WriteFile(cacheFile, []byte(hash), 0644)
	}

	return changed, nil
}

func md5Hex(b []byte) string {
	h := md5.Sum(b)
	return hex.EncodeToString(h[:])
}

func cacheFilePath(absFilePath string) string {
	cacheDir, err := os.UserCacheDir()
	if err != nil {
		cacheDir = filepath.Join(os.TempDir(), "goimports-reviser")
	} else {
		cacheDir = filepath.Join(cacheDir, "goimports-reviser")
	}
	key := md5Hex([]byte(absFilePath))
	return filepath.Join(cacheDir, key)
}

// findProjectName walks upwards from the given path to find go.mod and return the module name.
func findProjectName(path string) (string, error) {
	abs, err := filepath.Abs(path)
	if err != nil {
		return "", err
	}
	info, err := os.Stat(abs)
	if err == nil && !info.IsDir() {
		abs = filepath.Dir(abs)
	}
	dir := abs
	for {
		gomod := filepath.Join(dir, "go.mod")
		if data, err := ioutil.ReadFile(gomod); err == nil {
			for _, line := range strings.Split(string(data), "\n") {
				line = strings.TrimSpace(line)
				if strings.HasPrefix(line, "module ") {
					name := strings.TrimSpace(strings.TrimPrefix(line, "module"))
					// Strip quotes and optional comment
					if idx := strings.Index(name, "//"); idx >= 0 {
						name = strings.TrimSpace(name[:idx])
					}
					name = strings.Trim(name, "\"")
					return name, nil
				}
			}
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", fmt.Errorf("open go.mod: no such file or directory")
		}
		dir = parent
	}
}
