// reviseFile takes the file content and processes it.
// Returns the new content, whether content changed, and an error.
func reviseFile(filePath string, origContent []byte, projectName string, cfg *Config) ([]byte, bool, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, filePath, origContent, parser.ParseComments)
	if err != nil {
