	imports := collectImports(f)

	// Remove unused imports if requested
	if cfg.RemoveUnused {
		imports = removeUnused(f, imports)
	}

	// Apply set-alias heuristic
	if cfg.SetAlias {
		for i := range imports {
			if imports[i].Alias == "" || imports[i].Alias == "_" || imports[i].Alias == "." {
				continue
			}
		}
