	newContent, err := rebuildFile(fset, f, origContent, newImportBlock, cfg)
	if err != nil {
		return nil, false, err
	}

	changed := !bytes.Equal(origContent, newContent)
	return newContent, changed, nil
}

// isGenerated checks whether the first comment starts with "// Code generated".
func isGenerated(f *ast.File) bool {
	if len(f.Comments) == 0 {
		return false
	}
	first := f.Comments[0]
	if len(first.List) == 0 {
		return false
	}
	text := first.List[0].Text
	return strings.HasPrefix(text, "// Code generated")
}

func collectImports(f *ast.File) []importEntry {
	var imports []importEntry
	for _, decl := range f.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok || gd.Tok != token.IMPORT {
			continue
		}
		for _, spec := range gd.Specs {
			is := spec.(*ast.ImportSpec)
			pathVal, _ := strconv.Unquote(is.Path.Value)
			alias := ""
			if is.Name != nil {
				alias = is.Name.Name
			}
			comment := ""
			if is.Comment != nil && len(is.Comment.List) > 0 {
				// Join all comments, strip leading
				var parts []string
				for _, c := range is.Comment.List {
					parts = append(parts, c.Text)
				}
				comment = strings.Join(parts, " ")
			}
			imports = append(imports, importEntry{
				Alias:   alias,
				Path:    pathVal,
				Comment: comment,
			})
		}
	}
	return imports
}

func dedupeImports(imports []importEntry) []importEntry {
	seen := make(map[string]bool)
	var result []importEntry
	for _, imp := range imports {
		key := imp.Alias + " " + imp.Path
		if seen[key] {
			continue
		}
		seen[key] = true
		result = append(result, imp)
	}
	return result
}

var versionRe = regexp.MustCompile(`^v[0-9]+$`)

func versionedAlias(p string) string {
	parts := strings.Split(p, "/")
	if len(parts) < 2 {
		return ""
	}
	last := parts[len(parts)-1]
	if versionRe.MatchString(last) {
		return parts[len(parts)-2]
	}
	return ""
}

// classifyImport returns the category for an import.
// Categories: "std", "general", "company", "project", "blanked", "dotted"
func classifyImport(imp importEntry, projectName string, companyPrefixes []string, order []string) string {
	// If blanked/dotted are separate groups, they override category
	if imp.Alias == "_" && HasGroup(order, GroupBlanked) {
		return GroupBlanked
	}
	if imp.Alias == "." && HasGroup(order, GroupDotted) {
		return GroupDotted
	}

	// Is project?
	if projectName != "" && (imp.Path == projectName || strings.HasPrefix(imp.Path, projectName+"/")) {
		return GroupProject
	}

	// Is company?
	for _, cp := range companyPrefixes {
		if imp.Path == cp || strings.HasPrefix(imp.Path, cp+"/") {
			return GroupCompany
		}
	}

	// Is std? Standard library imports don't have a "." in the first path segment.
	first := imp.Path
	if idx := strings.Index(first, "/"); idx >= 0 {
		first = first[:idx]
	}
	if !strings.Contains(first, ".") {
		return GroupStd
	}

	return GroupGeneral
}

// buildImportBlock builds the full import block string.
func buildImportBlock(imports []importEntry, projectName string, cfg *Config) string {
	if len(imports) == 0 {
		return ""
	}

	// Group imports
	groups := make(map[string][]importEntry)
	for _, imp := range imports {
		cat := classifyImport(imp, projectName, cfg.CompanyPrefixes, cfg.ImportsOrder)
		groups[cat] = append(groups[cat], imp)
	}

	// Sort within each group (by path)
	for k := range groups {
		sort.SliceStable(groups[k], func(i, j int) bool {
			return groups[k][i].Path < groups[k][j].Path
		})
	}

	// Build groups in the specified order
	var groupOrder []string
	for _, g := range cfg.ImportsOrder {
		if _, ok := groups[g]; ok {
			groupOrder = append(groupOrder, g)
		}
	}

	// Build output
	var sb strings.Builder
	sb.WriteString("import (\n")

	first := true
	for _, g := range groupOrder {
		entries := groups[g]
		if len(entries) == 0 {
			continue
		}
		if !first {
			sb.WriteString("\n")
		}
		first = false

		if cfg.SeparateNamed {
			// Split into non-named and named
			var nonNamed, named []importEntry
			for _, e := range entries {
				if e.Alias == "" {
					nonNamed = append(nonNamed, e)
				} else {
					named = append(named, e)
				}
			}
			wrote := false
			if len(nonNamed) > 0 {
				writeEntries(&sb, nonNamed)
				wrote = true
			}
			if len(named) > 0 {
				if wrote {
					sb.WriteString("\n")
				}
				writeEntries(&sb, named)
			}
		} else {
			writeEntries(&sb, entries)
		}
	}

	sb.WriteString(")")
	return sb.String()
}

func writeEntries(sb *strings.Builder, entries []importEntry) {
	for _, e := range entries {
		sb.WriteString("\t")
		if e.Alias != "" {
			sb.WriteString(e.Alias)
			sb.WriteString(" ")
		}
		sb.WriteString(strconv.Quote(e.Path))
		if e.Comment != "" {
			sb.WriteString(" ")
			sb.WriteString(e.Comment)
		}
		sb.WriteString("\n")
	}
}

// removeUnused removes imports that appear unused based on AST usage.
// This is a heuristic: it checks for usage of the alias or last path segment as a selector.
func removeUnused(f *ast.File, imports []importEntry) []importEntry {
	// Collect used package-level identifiers
	used := make(map[string]bool)
	// Walk the file to find used identifiers
	ast.Walk(usageVisitor{used: used}, f)

	var result []importEntry
	for _, imp := range imports {
		// Blanked/dotted are always kept
		if imp.Alias == "_" || imp.Alias == "." {
			result = append(result, imp)
			continue
		}
		name := imp.Alias
		if name == "" {
			name = guessPkgName(imp.Path)
		}
		if used[name] {
			result = append(result, imp)
		}
	}
	return result
}

type usageVisitor struct {
	used map[string]bool
}

func (v usageVisitor) Visit(node ast.Node) ast.Visitor {
	switch n := node.(type) {
	case *ast.SelectorExpr:
		if id, ok := n.X.(*ast.Ident); ok {
			v.used[id.Name] = true
		}
	case *ast.Ident:
		v.used[n.Name] = true
	}
	return v
}

func guessPkgName(p string) string {
	base := path.Base(p)
	if versionRe.MatchString(base) {
		parts := strings.Split(p, "/")
		if len(parts) >= 2 {
			return parts[len(parts)-2]
		}
	}
	return base
}

// rebuildFile reconstructs the file content by replacing the import block.
func rebuildFile(fset *token.FileSet, f *ast.File, origContent []byte, newImportBlock string, cfg *Config) ([]byte, error) {
	// Find all import decls
	var importDecls []*ast.GenDecl
	for _, decl := range f.Decls {
		if gd, ok := decl.(*ast.GenDecl); ok && gd.Tok == token.IMPORT {
			importDecls = append(importDecls, gd)
		}
	}

	// Remove all import decls from the AST
	var newDecls []ast.Decl
	for _, decl := range f.Decls {
		if gd, ok := decl.(*ast.GenDecl); ok && gd.Tok == token.IMPORT {
			continue
		}
		newDecls = append(newDecls, decl)
	}
	f.Decls = newDecls

	// Also remove import-related comments from f.Comments, to avoid stray comments
	if len(importDecls) > 0 {
		minPos := importDecls[0].Pos()
		maxPos := importDecls[0].End()
		for _, d := range importDecls {
			if d.Pos() < minPos {
				minPos = d.Pos()
			}
			if d.End() > maxPos {
				maxPos = d.End()
			}
			// Include any nested comment group positions
			for _, s := range d.Specs {
				is := s.(*ast.ImportSpec)
				if is.Doc != nil && is.Doc.Pos() < minPos {
					minPos = is.Doc.Pos()
				}
				if is.Comment != nil && is.Comment.End() > maxPos {
					maxPos = is.Comment.End()
				}
			}
		}
		var filtered []*ast.CommentGroup
		for _, cg := range f.Comments {
			if cg.Pos() >= minPos && cg.End() <= maxPos {
				continue
			}
			filtered = append(filtered, cg)
		}
		f.Comments = filtered
	}

	// Print the AST with imports removed
	var buf bytes.Buffer
	cfgPrinter := &printer.Config{Mode: printer.UseSpaces | printer.TabIndent, Tabwidth: 8}
	if err := cfgPrinter.Fprint(&buf, fset, f); err != nil {
		return nil, err
	}
	withoutImports := buf.Bytes()

	// Find where to insert the import block: after the package declaration.
	lines := bytes.Split(withoutImports, []byte("\n"))
	var result bytes.Buffer
	inserted := false
	pkgLineIdx := -1
	for i, line := range lines {
		if bytes.HasPrefix(bytes.TrimSpace(line), []byte("package ")) {
			pkgLineIdx = i
			break
		}
	}

	if newImportBlock == "" {
		// No imports, just ensure gofmt
		for i, line := range lines {
			if i > 0 {
				result.WriteByte('\n')
			}
			result.Write(line)
		}
	} else {
		// Insert import block after the package declaration line
		for i, line := range lines {
			if i > 0 {
				result.WriteByte('\n')
			}
			result.Write(line)
			if i == pkgLineIdx && !inserted {
				result.WriteString("\n\n")
				result.WriteString(newImportBlock)
				inserted = true
				// Skip any blank lines immediately after
				// We'll handle that by not re-emitting blank
			}
		}
	}

	// Now format the output with gofmt for consistency
	out := result.Bytes()

	// Collapse sequence: after our inserted block, there may be a "\n" (from our "\n\n") then
	// the next line which might be "" (since original had blank line after package). Let gofmt handle.
	formatted, err := format.Source(out)
	if err != nil {
		return out, nil
	}

	// If format flag is set, also apply extra spacing between top-level decls
	if cfg.Format {
		formatted = addDeclSpacing(formatted)
	}

	return formatted, nil
}

// addDeclSpacing adds blank lines between adjacent top-level declarations (crude heuristic).
func addDeclSpacing(src []byte) []byte {
	// Parse again
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "", src, parser.ParseComments)
	if err != nil {
		return src
	}
	// Emit with blank lines between top-level decls
	var buf bytes.Buffer
	cfgPrinter := &printer.Config{Mode: printer.UseSpaces | printer.TabIndent, Tabwidth: 8}
	cfgPrinter.Fprint(&buf, fset, f)
	// A simpler approach: iterate through source lines and insert a blank line before each top-level func/var/type/const that starts right after another top-level decl without blank
	lines := strings.Split(buf.String(), "\n")
	var out []string
	prevDeclEnd := -2
	for i := 0; i < len(lines); i++ {
		line := lines[i]
		trimmed := strings.TrimLeft(line, " \t")
		// Top-level decl heuristic
		isTopLevelDecl := false
		if len(trimmed) > 0 && !strings.HasPrefix(line, "\t") && !strings.HasPrefix(line, " ") {
			if strings.HasPrefix(trimmed, "func ") || strings.HasPrefix(trimmed, "var ") || strings.HasPrefix(trimmed, "type ") || strings.HasPrefix(trimmed, "const ") {
				isTopLevelDecl = true
			}
		}
		if isTopLevelDecl && i > 0 && prevDeclEnd >= 0 && i == prevDeclEnd+1 {
			// Previous line was end of a decl; add blank
			out = append(out, "")
		}
		out = append(out, line)

		// Track end of decl: line == "}" at col 0
		if line == "}" {
			prevDeclEnd = len(out) - 1
		} else if isTopLevelDecl && strings.HasSuffix(trimmed, "{}") {
			prevDeclEnd = len(out) - 1
		} else if isTopLevelDecl && !strings.Contains(line, "{") {
			// Single-line decl like "var x = 5"
			prevDeclEnd = len(out) - 1
		}
	}
	result := strings.Join(out, "\n")
	// Re-format with gofmt to normalize
	if formatted, err := format.Source([]byte(result)); err == nil {
		return formatted
	}
	return []byte(result)
}
