		if newImportBlock == "" {
			// gofmt only
			formatted, err := format.Source(origContent)
			if err != nil {
				return origContent, nil
			}
			if cfg.Format {
				formatted = addDeclSpacing(formatted)
			}
			return formatted, nil
		}
		// Need to insert import block after package decl.
		pkgEnd := f.Name.End()
		offset := fset.Position(pkgEnd).Offset
		// Find end of the package decl line (to insert after).
		// Scan for next newline after pkgEnd offset.
