		buf.WriteString("\\n\\n")
		buf.WriteString(newImportBlock)
		if nlIdx < len(origContent) {
			buf.Write(origContent[nlIdx:])
		}
		result = buf.Bytes()
	} else {
		// Compute replacement range: from first import decl (including its Doc if any)
		// to last import decl (end).
		startOffset := fset.Position(importDecls[0].Pos()).Offset
		if importDecls[0].Doc != nil {
			startOffset = fset.Position(importDecls[0].Doc.Pos()).Offset
		}
		endOffset := fset.Position(importDecls[len(importDecls)-1].End()).Offset

		// Extend endOffset to include the trailing newline, if any
		if endOffset < len(origContent) && origContent[endOffset] == \'\\n\' {
			endOffset++
		}

		// For multiple non-contiguous import decls, also remove intermediate content (rare)
		// between decls that consists purely of blank lines.
		// For simplicity, just replace the whole span.

		var buf bytes.Buffer
		buf.Write(origContent[:startOffset])
		if newImportBlock != "" {
			buf.WriteString(newImportBlock)
			buf.WriteString("\\n")
		}
		buf.Write(origContent[endOffset:])
