					result = buf2.Bytes()
				}
			}
		}
	}

	// Format with gofmt
	formatted, err := format.Source(result)
	if err != nil {
		return result, nil
	}

	if cfg.Format {
		formatted = addDeclSpacing(formatted)
	}

	return formatted, nil
}

'''

# Replace old function with new one
match = re.search(r'// rebuildFile reconstructs the file content by replacing the import block\.\nfunc rebuildFile.*?\n^}\n', content, re.MULTILINE | re.DOTALL)
content = content[:match.start()] + new_func + content[match.end():]

with open('reviser/file.go', 'w') as f:
    f.write(content)
